package view;

import constants.Constants;
import constants.Message;
import dto.BookResponseDTO;
import java.util.ArrayList;
import java.util.List;

/**
 * Man hinh ket qua: chi in nhung gi Controller da dua vao qua thuoc tinh (setter).
 * Ham in display() khong nhan tham so va duoc goi dung 1 lan cho moi luong xu ly.
 *
 * @author CuongThai Academy
 */
public class BookView {

    // Cac dong bang can in (rong thi khong in bang)
    private List<BookResponseDTO> responseList;

    // Cau thong bao can in (rong thi khong in)
    private String message;

    // Tao View rong
    public BookView() {
        responseList = new ArrayList<>();
        message = "";
    }

    // Controller dua cac dong bang vao View
    public void setResponseList(List<BookResponseDTO> responseList) {
        this.responseList = responseList;
    }

    // Controller dua cau thong bao vao View
    public void setMessage(String message) {
        this.message = message;
    }

    // In ket qua dang giu: cau thong bao (neu co) roi bang sach (neu co)
    public void display() {
        // Co cau thong bao thi in
        if (!message.isEmpty()) {
            System.out.println(message);
        }

        // Co dong bang thi in tieu de cot roi tung dong
        if (!responseList.isEmpty()) {
            System.out.println(String.format(Constants.TABLE_FORMAT, Message.COLUMN_NO,
                    Message.COLUMN_ISBN, Message.COLUMN_TITLE));

            // In tung dong sach
            for (BookResponseDTO row : responseList) {
                System.out.println(row.toString());
            }
        }
    }
}

