package repository;

import constants.Message;
import dto.BookRequestDTO;
import dto.BookResponseDTO;
import java.util.ArrayList;
import java.util.List;
import model.Book;

/**
 * Kho sach: GIU danh sach Book va lam CRUD tren no (them, tim, lay het).
 * Chi Controller goi kho; Service khong bao gio cham vao kho.
 *
 * @author CuongThai Academy
 */
public class BookRepository {

    // Danh sach sach dang co trong thu vien
    private List<Book> bookList;

    // Tao kho rong
    public BookRepository() {
        bookList = new ArrayList<>();
    }

    // Them 1 sach tu phieu nhap; ISBN da co thi nem loi (khong them)
    public void addBook(BookRequestDTO bookRequestDTO) throws Exception {
        // Sach dang giu ISBN nay (null neu chua co)
        Book existingBook = findByIsbn(bookRequestDTO.getIsbn());

        // Trung ISBN thi bao ro sach nao dang giu ISBN do
        if (existingBook != null) {
            throw new Exception(String.format(Message.ERROR_DUPLICATE_ISBN,
                    existingBook.getIsbn(), existingBook.getTitle()));
        }

        // Doi phieu nhap thanh model roi them vao cuoi danh sach
        bookList.add(new Book(bookRequestDTO.getIsbn(), bookRequestDTO.getTitle()));
    }

    // Dem so dau sach dang co
    public int countBooks() {
        return bookList.size();
    }

    // Lay ban sao moi sach (dang dong bang) theo thu tu da them
    public List<BookResponseDTO> findAll() {
        // Danh sach dong bang tra ve
        List<BookResponseDTO> responseList = new ArrayList<>();

        // Moi sach doi thanh 1 dong bang
        for (Book book : bookList) {
            responseList.add(toResponseDTO(book));
        }

        return responseList;
    }

    // Tim sach co ten chua tu khoa (khong phan biet hoa thuong)
    public List<BookResponseDTO> findByKeyword(String keyword) {
        // Danh sach dong bang tim duoc; tu khoa viet thuong de so khong phan biet hoa thuong
        List<BookResponseDTO> foundList = new ArrayList<>();
        String lowerKeyword = keyword.toLowerCase();

        // Duyet tung sach de so ten
        for (Book book : bookList) {
            // Ten chua tu khoa thi giu lai
            if (book.getTitle().toLowerCase().contains(lowerKeyword)) {
                foundList.add(toResponseDTO(book));
            }
        }

        return foundList;
    }

    // Tim sach theo ISBN; khong co thi tra null
    private Book findByIsbn(String isbn) {
        // Duyet tung sach de so ISBN
        for (Book book : bookList) {
            // So chuoi bang equals, khong bao gio bang ==
            if (book.getIsbn().equals(isbn)) {
                return book;
            }
        }

        return null;
    }

    // Chep du lieu 1 Book sang 1 dong bang moi
    private BookResponseDTO toResponseDTO(Book book) {
        return new BookResponseDTO(book.getIsbn(), book.getTitle());
    }
}

package service;

import dto.BookResponseDTO;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * Nghiep vu sach: sap xep va danh so cac dong bang Controller dua vao.
 * Service CHI xu ly du lieu duoc dua vao — khong tao, khong goi kho (repository).
 *
 * @author CuongThai Academy
 */
public class BookService {

    // Service khong giu du lieu nao
    public BookService() {
    }

    // Sap cac dong bang theo ten (A-Z, khong phan biet hoa thuong), trung ten thi theo ISBN;
    // xong danh so thu tu tu 1
    public List<BookResponseDTO> sortByTitle(List<BookResponseDTO> bookList) {
        // Ban sao de khong lam doi thu tu cua danh sach goc
        List<BookResponseDTO> sortedList = new ArrayList<>(bookList);

        // Comparator la "luat so": tra so am neu first dung truoc second
        Collections.sort(sortedList, new Comparator<BookResponseDTO>() {
            // So ten truoc, trung ten thi so ISBN
            @Override
            public int compare(BookResponseDTO first, BookResponseDTO second) {
                // Ket qua so ten (0 = trung ten)
                int byTitle = first.getTitle().compareToIgnoreCase(second.getTitle());

                // Trung ten thi ISBN quyet dinh thu tu
                if (byTitle == 0) {
                    return first.getIsbn().compareTo(second.getIsbn());
                }

                return byTitle;
            }
        });

        // Danh so thu tu sau khi sap xep
        for (int i = 0; i < sortedList.size(); i++) {
            sortedList.get(i).setNo(i + 1);
        }

        return sortedList;
    }
}

